mapper.select:
SELECT C.* FROM public."LNK_リンククリップ情報" C
WHERE  AND C."URL正規化" = #{normalizedUrl}
ORDER BY C."リンククリップID" DESC

mapper.update:
UPDATE public."LNK_リンククリップ情報"
   SET "閲覧回数" = "閲覧回数" + 1, "最終閲覧日時" = CURRENT_TIMESTAMP, "既読" = TRUE,
       "更新者アカウントID" = #{ownerAccountId}
 WHERE "所有者アカウントID" = #{ownerAccountId} AND "リンククリップID" = #{linkClipId}
